def format_rag_prompt(user_query: str, retrieved_docs: list[str]) -> str:
    context_block = '\n\n'.join(f'[Doc {i+1}]: {doc}' for i, doc in enumerate(retrieved_docs))
    return (
        f'System: Answer the user query using only the provided context. If unknown, say so.\n\n'
        f'Context:\n{context_block}\n\n'
        f'User Question: {user_query}\n'
        f'Assistant:'
    )

prompt = format_rag_prompt('What is our refund policy?', ['Refunds are accepted within 30 days of purchase.'])
print(prompt)
